+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+
+const fullNameError = document.getElementById('fullNameError');
+const emailError = document.getElementById('emailError');
+const phoneError = document.getElementById('phoneError');
+
+const validationRules = {
+    fullName: {
+        input: fullNameInput,
+        errorElement: fullNameError,
+        validate: (value) => {
+            if (!value.trim()) {
+                return 'Full name is required';
+            }
+            if (value.trim().length < 2) {
+                return 'Full name must be at least 2 characters';
+            }
+            return '';
+        }
+    },
+    email: {
+        input: emailInput,
+        errorElement: emailError,
+        validate: (value) => {
+            if (!value.trim()) {
+                return 'Email address is required';
+            }
+            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+            if (!emailRegex.test(value)) {
+                return 'Please enter a valid email address';
+            }
+            return '';
+        }
+    },
+    phone: {
+        input: phoneInput,
+        errorElement: phoneError,
+        validate: (value) => {
+            if (!value.trim()) {
+                return '';
+            }
+            const phoneRegex = /^(\(\d{3}\)\s?\d{3}-\d{4}|\+1-\d{3}-\d{3}-\d{4})$/;
+            if (!phoneRegex.test(value.trim())) {
+                return 'Please use format: (555) 123-4567 or +1-555-123-4567';
+            }
+            return '';
+        }
+    }
+};
+
+function validateField(fieldName) {
+    const rule = validationRules[fieldName];
+    if (!rule) return '';
+
+    const value = rule.input.value;
+    const error = rule.validate(value);
+
+    if (error) {
+        rule.input.setAttribute('aria-invalid', 'true');
+        rule.errorElement.textContent = error;
+    } else {
+        rule.input.setAttribute('aria-invalid', 'false');
+        rule.errorElement.textContent = '';
+    }
+
+    return error;
+}
+
+function getFirstInvalidField() {
+    const fields = ['fullName', 'email', 'phone'];
+    for (const fieldName of fields) {
+        const error = validateField(fieldName);
+        if (error) {
+            return validationRules[fieldName].input;
+        }
+    }
+    return null;
+}
+
+fullNameInput.addEventListener('blur', () => validateField('fullName'));
+emailInput.addEventListener('blur', () => validateField('email'));
+phoneInput.addEventListener('blur', () => validateField('phone'));
+
+fullNameInput.addEventListener('input', () => {
+    if (fullNameInput.hasAttribute('aria-invalid') && fullNameInput.getAttribute('aria-invalid') === 'true') {
+        validateField('fullName');
+    }
+});
+
+emailInput.addEventListener('input', () => {
+    if (emailInput.hasAttribute('aria-invalid') && emailInput.getAttribute('aria-invalid') === 'true') {
+        validateField('email');
+    }
+});
+
+phoneInput.addEventListener('input', () => {
+    if (phoneInput.hasAttribute('aria-invalid') && phoneInput.getAttribute('aria-invalid') === 'true') {
+        validateField('phone');
+    }
+});
+
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    const firstInvalidField = getFirstInvalidField();
+
+    if (firstInvalidField) {
+        firstInvalidField.focus();
+        return;
+    }
+
+    const formData = {
+        fullName: fullNameInput.value.trim(),
+        email: emailInput.value.trim(),
+        phone: phoneInput.value.trim() || null
+    };
+
+    console.log('Form submitted with data:', formData);
+    alert(`Thank you, ${formData.fullName}! We'll get back to you at ${formData.email} soon.`);
+
+    form.reset();
+    fullNameInput.setAttribute('aria-invalid', 'false');
+    emailInput.setAttribute('aria-invalid', 'false');
+    phoneInput.setAttribute('aria-invalid', 'false');
+    fullNameError.textContent = '';
+    emailError.textContent = '';
+    phoneError.textContent = '';
+});
+
")

